#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with slurm
# installed with the default option (apptainer auto, no Apptainer in the image), after the start hook ran once.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=/dev/null
source "$(dirname "$0")/helpers.sh"

check "the Slurm commands and daemons are installed" bash -c 'command -v sbatch squeue sinfo srun scontrol && test -x /usr/sbin/slurmctld && test -x /usr/sbin/slurmd && test -x /usr/sbin/munged'
check "the slurm and munge system users exist" bash -c 'getent passwd slurm && getent passwd munge'
check "the start hook exists and is executable" test -x "${SLURM_HOOK}"
check "the configuration directory is the mounted volume" config_dir_is_mount
check "the seeded slurm.conf starts with the marker line" marker_is_first_line
check "the identity lines name this container" identity_lines_aligned
check "the MUNGE key was generated at the first start, readable only by munge" munge_key_from_first_start
check "one munged, one slurmctld, and one slurmd run" one_of_each_daemon
check "the seeded partition lists its one node idle" bash -c 'node_idle && seeded_partition_listed'
check "sbatch --wait runs a job printing the hostname to completion" batch_job_completes
check "sbatch --test-only reports a start time and queues nothing" test_only_queues_nothing
pids_before="$(daemon_pids)"
check "a repeated start exits zero" hook "" ""
check "the repeated start keeps the daemons' process ids" test "$(daemon_pids)" = "${pids_before}"
check "without Apptainer no backend template and no oci.conf exist" no_backend_files
check "no temporary install directory remains" bash -c '! compgen -G "/tmp/slurm-install.*"'

reportResults
